CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'user', UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE POLICY "Read own role" ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY "Read own or admin profiles" ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "Update own name" ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
REVOKE UPDATE ON public.profiles FROM authenticated;
GRANT UPDATE(full_name) ON public.profiles TO authenticated;
CREATE TABLE public.tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, symbol text NOT NULL UNIQUE, network text NOT NULL DEFAULT 'Ethereum', contract_address text NOT NULL DEFAULT '', decimals integer NOT NULL DEFAULT 18 CHECK(decimals BETWEEN 0 AND 30), price numeric NOT NULL DEFAULT 0 CHECK(price>=0), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.tokens TO authenticated;
GRANT ALL ON public.tokens TO service_role;
ALTER TABLE public.tokens ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Members read tokens" ON public.tokens FOR SELECT TO authenticated USING(true);
CREATE POLICY "Admin manages tokens" ON public.tokens FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.balances (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, token_id uuid NOT NULL REFERENCES public.tokens(id) ON DELETE CASCADE, amount numeric NOT NULL DEFAULT 0 CHECK(amount>=0), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,token_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.balances TO authenticated;
GRANT ALL ON public.balances TO service_role;
ALTER TABLE public.balances ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own or admin balances" ON public.balances FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin assigns balances" ON public.balances FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.handle_wallet_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name,email) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'full_name',''),coalesce(NEW.email,'')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'user'); RETURN NEW; END $$;
CREATE TRIGGER wallet_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_wallet_signup();